1	/* ExamRadar site — all data is read from site/data/*.json, nothing is hardcoded. */
2	(function () {
3	  "use strict";
4	
5	  var COVERAGE_URL = "data/sample-coverage.json";
6	  var SESSIONS_URL = "data/qoder-sessions.json";
7	  var USAGE_URL = "data/usage-summary.json";
8	  var DEMO_VIDEO = "media/demo.mp4";
9	
10	  var LEVEL_LABEL = { covered: "已覆盖", thin: "薄弱", missing: "缺失" };
11	  var QUESTION_SNIPPET = 60;
12	
13	  function esc(s) {
14	    return String(s == null ? "" : s)
15	      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
16	      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
17	  }
18	
19	  function fmtNum(v, digits) {
20	    if (v == null || isNaN(v)) return "—";
21	    return Number(v).toFixed(digits == null ? 2 : digits);
22	  }
23	
24	  function fmtCredits(v) {
25	    if (v == null || isNaN(v)) return "—";
26	    return String(Math.round(v * 100) / 100);
27	  }
28	
29	  function renderMarkdown(text) {
30	    if (typeof marked === "undefined") return "<p>" + esc(text) + "</p>";
31	    try {
32	      return marked.parse(esc(text));
33	    } catch (e) {
34	      return "<p>" + esc(text) + "</p>";
35	    }
36	  }
37	
38	  function levelBadge(level) {
39	    return level && LEVEL_LABEL[level]
40	      ? '<span class="badge ' + level + '">' + LEVEL_LABEL[level] + "</span>"
41	      : '<span class="badge unknown">未知</span>';
42	  }
43	
44	  /* ---------- screenshot placeholders: imgFallback lives in index.html <head> ---------- */
45	
46	  /* ---------- coverage snapshot ---------- */
47	  function loadCoverage() {
48	    return fetch(COVERAGE_URL)
49	      .then(function (r) { return r.ok ? r.json() : null; })
50	      .then(function (data) {
51	        var empty = !data || !Array.isArray(data.items) || data.items.length === 0;
52	        document.getElementById("radar-empty").hidden = !empty;
53	        document.getElementById("radar-chart").style.display = empty ? "none" : "";
54	        document.getElementById("blind-empty").hidden = !empty;
55	        if (empty) return;
56	        renderRadarMeta(data);
57	        renderRadarChart(data);
58	        renderBlindList(data);
59	      })
60	      .catch(function () {
61	        document.getElementById("radar-empty").hidden = false;
62	        document.getElementById("blind-empty").hidden = false;
63	      });
64	  }
65	
66	  function fmtLocalTime(iso) {
67	    var d = new Date(iso);
68	    if (isNaN(d.getTime())) return "";
69	    var pad = function (n) { return (n < 10 ? "0" : "") + n; };
70	    var local = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate()) +
71	      " " + pad(d.getHours()) + ":" + pad(d.getMinutes());
72	    var off = -d.getTimezoneOffset();
73	    var sign = off >= 0 ? "+" : "-";
74	    var abs = Math.abs(off);
75	    var tz = "UTC" + sign + Math.floor(abs / 60) + (abs % 60 ? ":" + pad(abs % 60) : "");
76	    return local + "（访问者本地时间，" + tz + "）";
77	  }
78	
79	  function methodText(config) {
80	    if (!config) return "";
81	    if (config.term_ratio_covered != null || config.support_chars_covered != null ||
82	        config.min_body_chars != null) {
83	      var parts = [];
84	      if (config.term_ratio_covered != null)
85	        parts.push("考点词找到比例阈值 " + config.term_ratio_covered);
86	      if (config.support_chars_covered != null)
87	        parts.push("支撑正文字数阈值 " + config.support_chars_covered + " 字");
88	      if (config.min_body_chars != null)
89	        parts.push("计入支撑的最小段字数 " + config.min_body_chars + " 字");
90	      return "判定规则：一个考点词（含别名）都没找到 → 缺失；找到比例与支撑字数都达到阈值 → 已覆盖；其余 → 薄弱。" +
91	        "（" + parts.join("；") + "）";
92	    }
93	    var legacy = [];
94	    if (config.t_covered != null) legacy.push("covered ≥ " + config.t_covered);
95	    if (config.t_thin != null) legacy.push("thin ≥ " + config.t_thin);
96	    return legacy.length ? "判定阈值：" + legacy.join("，") : "";
97	  }
98	
99	  function renderRadarMeta(data) {
100	    var meta = document.getElementById("radar-meta");
101	    var bits = [];
102	    if (data.course_id) bits.push("课程 " + esc(data.course_id));
103	    if (Array.isArray(data.topics)) bits.push(data.topics.length + " 个知识点");
104	    if (data.created_at) bits.push("导出时间 " + esc(fmtLocalTime(data.created_at)));
105	    meta.textContent = bits.join(" · ");
106	    var th = document.getElementById("radar-method");
107	    if (th) th.textContent = methodText(data.config);
108	  }
109	
110	  function topicNames(data) {
111	    var names = {};
112	    (data.topics || []).forEach(function (t) { names[t.id] = t.name; });
113	    return names;
114	  }
115	
116	  function wrapAxisLabel(name, maxLine) {
117	    var s = String(name == null ? "" : name);
118	    if (!s) return "";
119	    var out = s.replace(/：/g, "：\n").replace(/（/g, "\n（");
120	    return out.split("\n").map(function (line) {
121	      if (line.length <= maxLine) return line;
122	      return line.match(new RegExp(".{1," + maxLine + "}", "g")).join("\n");
123	    }).join("\n");
124	  }
125	
126	  function renderRadarChart(data) {
127	    if (typeof echarts === "undefined") return;
128	    var el = document.getElementById("radar-chart");
129	    var narrow = el.clientWidth < 420;
130	    var maxLine = narrow ? 8 : 11;
131	    var names = topicNames(data);
132	    var items = data.items;
133	    var indicators = items.map(function (it) {
134	      return { name: wrapAxisLabel(it.topic_name || names[it.topic_id] || it.topic_id || "", maxLine), max: 1 };
135	    });
136	    var coverage = items.map(function (it) {
137	      return it.coverage_score == null ? 0 : Math.max(0, Math.min(1, it.coverage_score));
138	    });
139	    var maxWeight = 0;
140	    items.forEach(function (it) {
141	      if (typeof it.exam_weight === "number" && it.exam_weight > maxWeight) maxWeight = it.exam_weight;
142	    });
143	    var weight = items.map(function (it) {
144	      if (maxWeight <= 0 || it.exam_weight == null) return 0;
145	      return Math.max(0, Math.min(1, it.exam_weight / maxWeight));
146	    });
147	    var chart = echarts.init(el, null, { renderer: "svg" });
148	    chart.setOption({
149	      tooltip: {
150	        trigger: "item",
151	        confine: true,
152	        formatter: function (p) {
153	          var i = p.dataIndex;
154	          var it = items[i];
155	          var lv = LEVEL_LABEL[it.coverage_level] || it.coverage_level || "未知";
156	          return esc(it.topic_name || names[it.topic_id] || it.topic_id) + "<br/>" +
157	            "覆盖度：" + fmtNum(it.coverage_score, 4) + "（" + lv + "）<br/>" +
158	            "往年分值：" + (it.exam_weight == null ? "—" : it.exam_weight + " 分");
159	        }
160	      },
161	      legend: { bottom: 8, data: ["覆盖度", "考试权重（按最大分值归一化）"], textStyle: { fontSize: 12 } },
162	      radar: {
163	        indicator: indicators,
164	        radius: narrow ? "46%" : "58%",
165	        center: ["50%", "46%"],
166	        axisName: { color: "#4a5568", fontSize: narrow ? 10 : 11, lineHeight: narrow ? 13 : 15 },
167	        splitArea: { areaStyle: { color: ["#ffffff", "#f4f7fc"] } }
168	      },
169	      series: [{
170	        type: "radar",
171	        data: [
172	          {
173	            name: "覆盖度",
174	            value: coverage,
175	            itemStyle: { color: "#2456d6" },
176	            areaStyle: { color: "rgba(36,86,214,0.18)" },
177	            lineStyle: { width: 2 }
178	          },
179	          {
180	            name: "考试权重（按最大分值归一化）",
181	            value: weight,
182	            itemStyle: { color: "#e67e22" },
183	            areaStyle: { color: "rgba(230,126,34,0.12)" },
184	            lineStyle: { width: 2, type: "dashed" }
185	          }
186	        ]
187	      }]
188	    });
189	    window.addEventListener("resize", function () { chart.resize(); });
190	  }
191	
192	  /* ---------- blind spot list (shared detail builder, table + mobile cards) ---------- */
193	  function sortedItems(data) {
194	    return data.items.slice().sort(function (a, b) {
195	      var sa = a.blind_spot_score == null ? -1 : a.blind_spot_score;
196	      var sb = b.blind_spot_score == null ? -1 : b.blind_spot_score;
197	      if (sa !== sb) return sb - sa;
198	      return String(a.topic_id || "").localeCompare(String(b.topic_id || ""), "en");
199	    });
200	  }
201	
202	  function chunkRef(c) {
203	    var parts = [];
204	    if (c.doc) parts.push(esc(c.doc));
205	    if (typeof c.page === "number") parts.push("第 " + c.page + " 页");
206	    if (c.heading) parts.push(esc(c.heading));
207	    return parts.join(" · ");
208	  }
209	
210	  function termsHtml(it) {
211	    if (!Array.isArray(it.terms) || it.terms.length === 0) return "";
212	    var lis = it.terms.map(function (t) {
213	      var alias = Array.isArray(t.aliases) && t.aliases.length
214	        ? '<span class="term-alias">（别名：' + t.aliases.map(esc).join("、") + "）</span>" : "";
215	      var found = t.found
216	        ? '<span class="term-found">✓ 找到</span>'
217	        : '<span class="term-miss">✗ 没找到</span>';
218	      var chunks = "";
219	      if (t.found && Array.isArray(t.chunks) && t.chunks.length) {
220	        var shown = t.chunks.slice(0, 3).map(function (c) {
221	          return "<div>" + chunkRef(c) + "</div>";
222	        }).join("");
223	        if (t.chunks.length > 3)
224	          shown += '<div class="muted">…等共 ' + t.chunks.length + " 段</div>";
225	        chunks = '<div class="term-chunks">' + shown + "</div>";
226	      }
227	      return '<li><div class="term-line"><span class="term-name">' + esc(t.term) + "</span>" +
228	        alias + found + "</div>" + chunks + "</li>";
229	    });
230	    return '<h4 style="margin-top:14px">考点词明细</h4><ul class="term-list">' + lis.join("") + "</ul>";
231	  }
232	
233	  function supportHtml(it) {
234	    if (it.support_chunks == null && it.support_chars == null) return "";
235	    var chunks = it.support_chunks == null ? "—" : it.support_chunks;
236	    var chars = it.support_chars == null ? "—" : it.support_chars;
237	    return '<p class="muted" style="font-size:13px;margin:8px 0 0">支撑正文：' +
238	      chunks + " 段，共 " + chars + " 字</p>";
239	  }
240	
241	  function evidenceHtml(it) {
242	    var ev = it.best_evidence;
243	    if (!ev) return "";
244	    var html = '<h4 style="margin-top:14px">最强证据</h4><div class="evidence">';
245	    if (ev.content) html += '<div class="ev-content">' + renderMarkdown(ev.content) + "</div>";
246	    var parts = [];
247	    if (ev.document_name) parts.push(esc(ev.document_name));
248	    if (typeof ev.page === "number") parts.push("第 " + ev.page + " 页");
249	    if (ev.heading) parts.push(esc(ev.heading));
250	    var scores = [];
251	    if (ev.semantic_score != null) scores.push("语义分 " + fmtNum(ev.semantic_score, 4));
252	    if (ev.keyword_score != null) scores.push("关键词分 " + fmtNum(ev.keyword_score, 4));
253	    html += '<div class="ev-meta">' + parts.join(" · ") +
254	      (scores.length ? (parts.length ? " · " : "") + scores.join(" · ") : "") + "</div></div>";
255	    return html;
256	  }
257	
258	  function questionsHtml(it) {
259	    if (!Array.isArray(it.exam_questions) || it.exam_questions.length === 0) return "";
260	    var qs = it.exam_questions.map(function (q, qi) {
261	      var line = "第 " + esc(q.question_no) + " 题 · " +
262	        (q.points == null ? "分值未知" : q.points + " 分");
263	      if (Array.isArray(q.matched_terms) && q.matched_terms.length)
264	        line += " · 命中考点词：" + q.matched_terms.map(esc).join("、");
265	      if (q.similarity != null) line += " · 相似度 " + fmtNum(q.similarity, 3);
266	      var content = "";
267	      if (q.content) {
268	        var text = String(q.content);
269	        var snippet = text.slice(0, QUESTION_SNIPPET);
270	        var expandable = text.length > QUESTION_SNIPPET;
271	        var shortText = snippet + (expandable ? "…" : "");
272	        content = '<div class="q-content"><span class="q-snippet" data-short="' +
273	          esc(shortText) + '" data-full="' + esc(text) + '">' + esc(shortText) + "</span>";
274	        if (expandable)
275	          content += ' <button class="q-toggle" data-q="' + qi + '">展开原文</button>';
276	        content += "</div>";
277	      }
278	      return '<div class="q-item"><div class="q-line">' + line + "</div>" + content + "</div>";
279	    }).join("");
280	    return '<h4 style="margin-top:14px">关联的往年试题</h4>' + qs;
281	  }
282	
283	  function detailHtml(it) {
284	    var html = '<div class="detail-box">';
285	    if (it.reason)
286	      html += '<h4>判定理由</h4><p class="reason-text" style="margin-top:0">' + esc(it.reason) + "</p>";
287	    html += supportHtml(it) + termsHtml(it) + evidenceHtml(it) + questionsHtml(it);
288	    if (!it.reason && !it.best_evidence && !it.terms &&
289	        !(Array.isArray(it.exam_questions) && it.exam_questions.length))
290	      html += '<p class="muted" style="margin:0">这条记录缺少证据与试题数据。</p>';
291	    html += "</div>";
292	    return html;
293	  }
294	
295	  function toggleQuestion(btn) {
296	    var item = btn.closest(".q-item");
297	    var snippet = item.querySelector(".q-snippet");
298	    if (!snippet) return;
299	    var showing = btn.textContent === "收起原文";
300	    btn.textContent = showing ? "展开原文" : "收起原文";
301	    snippet.textContent = showing ? snippet.getAttribute("data-short") : snippet.getAttribute("data-full");
302	  }
303	
304	  function renderBlindList(data) {
305	    var names = topicNames(data);
306	    var items = sortedItems(data);
307	
308	    var tbody = document.getElementById("blind-tbody");
309	    var rowsHtml = "";
310	    var cardsHtml = "";
311	    items.forEach(function (it, idx) {
312	      var name = it.topic_name || names[it.topic_id] || it.topic_id || "—";
313	      var cov = fmtNum(it.coverage_score, 4);
314	      var weight = it.exam_weight == null ? "—" : it.exam_weight;
315	      var blind = fmtNum(it.blind_spot_score);
316	
317	      rowsHtml +=
318	        '<tr class="row-main" data-idx="' + idx + '">' +
319	        "<td>" + esc(name) + "</td>" +
320	        "<td>" + levelBadge(it.coverage_level) + "</td>" +
321	        '<td class="num">' + cov + "</td>" +
322	        '<td class="num">' + weight + "</td>" +
323	        '<td class="num">' + blind + "</td>" +
324	        '<td class="exp muted" style="text-align:center">&#9656;</td></tr>' +
325	        '<tr class="row-detail" data-detail="' + idx + '" hidden><td colspan="6">' + detailHtml(it) + "</td></tr>";
326	
327	      cardsHtml +=
328	        '<div class="blind-card"><div class="bc-head" data-idx="' + idx + '">' +
329	        '<span class="bc-name">' + esc(name) + "</span>" + levelBadge(it.coverage_level) +
330	        '<span class="exp muted">&#9656;</span></div>' +
331	        '<div class="bc-stats">' +
332	        "<div><b>" + cov + '</b>覆盖度</div>' +
333	        "<div><b>" + weight + '</b>往年分值</div>' +
334	        "<div><b>" + blind + '</b>盲区分值</div>' +
335	        "</div><div class=\"bc-detail\" data-idx=\"" + idx + "\" hidden>" + detailHtml(it) + "</div></div>";
336	    });
337	    tbody.innerHTML = rowsHtml;
338	    document.getElementById("blind-cards").innerHTML = cardsHtml;
339	
340	    function toggle(root, idx) {
341	      var head = root.querySelector('[data-idx="' + idx + '"]');
342	      var detail = root.querySelector('.row-detail[data-detail="' + idx + '"], .bc-detail[data-idx="' + idx + '"]');
343	      var open = !detail.hidden;
344	      detail.hidden = open;
345	      head.classList.toggle("open", !open);
346	      var exp = head.querySelector(".exp");
347	      if (exp) exp.innerHTML = open ? "&#9656;" : "&#9662;";
348	    }
349	
350	    tbody.addEventListener("click", function (e) {
351	      if (e.target.closest(".q-toggle")) { toggleQuestion(e.target.closest(".q-toggle")); return; }
352	      var tr = e.target.closest("tr.row-main");
353	      if (tr) toggle(tbody, tr.getAttribute("data-idx"));
354	    });
355	    var cards = document.getElementById("blind-cards");
356	    cards.addEventListener("click", function (e) {
357	      if (e.target.closest(".q-toggle")) { toggleQuestion(e.target.closest(".q-toggle")); return; }
358	      var head = e.target.closest(".bc-head");
359	      if (head) toggle(cards, head.getAttribute("data-idx"));
360	    });
361	  }
362	
363	  /* ---------- qoder sessions ---------- */
364	  function loadSessions() {
365	    return fetch(SESSIONS_URL)
366	      .then(function (r) { return r.ok ? r.json() : null; })
367	      .then(function (data) {
368	        var wrap = document.getElementById("sessions-body");
369	        var totalRow = document.getElementById("sessions-total");
370	        if (!data || !Array.isArray(data.rows) || data.rows.length === 0) {
371	          wrap.innerHTML = '<tr><td colspan="6" class="muted">会话数据不可用。</td></tr>';
372	          totalRow.hidden = true;
373	          return;
374	        }
375	        var html = "";
376	        data.rows.forEach(function (r) {
377	          var modelCls = /GLM/i.test(r.model || "") ? "model-tag glm" : "model-tag";
378	          html +=
379	            "<tr>" +
380	            "<td>" + esc(r.id == null ? "—" : r.id) + "</td>" +
381	            '<td class="title-cell">' + esc(r.title || "—") + "</td>" +
382	            "<td class=" + JSON.stringify(modelCls) + ">" + esc(r.model || "—") + "</td>" +
383	            '<td class="num">' + (r.turns == null ? "—" : r.turns) + "</td>" +
384	            "<td>" + esc(r.duration || "—") + "</td>" +
385	            '<td class="num">' + fmtCredits(r.credits) + "</td>" +
386	            "</tr>";
387	        });
388	        wrap.innerHTML = html;
389	        var t = data.totals || {};
390	        document.getElementById("total-rows").textContent = t.rows != null ? t.rows : "—";
391	        document.getElementById("total-turns").textContent = t.turns != null ? t.turns : "—";
392	        document.getElementById("total-credits").textContent = t.credits != null ? fmtCredits(t.credits) : "—";
393	      })
394	      .catch(function () {
395	        document.getElementById("sessions-body").innerHTML =
396	          '<tr><td colspan="6" class="muted">会话数据不可用。</td></tr>';
397	        document.getElementById("sessions-total").hidden = true;
398	      });
399	  }
400	
401	  /* ---------- usage summary: three optional blocks ---------- */
402	  function statCard(value, label, unit) {
403	    return '<div class="stat"><div class="v">' + (value == null ? "—" : esc(value)) +
404	      '</div><div class="k">' + esc(label) + (unit && value != null ? " · " + esc(unit) : "") + "</div></div>";
405	  }
406	
407	  function srcLine(obj) {
408	    var parts = [];
409	    if (obj && obj.source) parts.push("来源：" + esc(obj.source));
410	    if (obj && obj.exported_at) parts.push("导出时间：" + esc(obj.exported_at));
411	    return parts.length ? '<p class="usage-src">' + parts.join(" · ") + "</p>" : "";
412	  }
413	
414	  function loadUsage() {
415	    return fetch(USAGE_URL)
416	      .then(function (r) { return r.ok ? r.json() : null; })
417	      .then(function (data) {
418	        var collecting = document.getElementById("usage-collecting");
419	        var filled = document.getElementById("usage-filled");
420	        if (!data || data.status === "collecting") return;
421	        var blocks = [];
422	
423	        var site = data.site_stats;
424	        if (site && (site.pv != null || site.uv != null)) {
425	          var period = site.period ? "（" + esc(site.period) + "）" : "";
426	          blocks.push('<div class="usage-block"><h3>Qoder Sites 访问统计' + period + "</h3>" +
427	            '<div class="usage-stats">' +
428	            statCard(site.pv, "页面浏览 PV") + statCard(site.uv, "独立访客 UV") +
429	            "</div>" + srcLine(site) + "</div>");
430	        }
431	
432	        var usage = data.usage || {
433	          usage_days: data.usage_days, study_sessions: data.study_sessions,
434	          questions_answered: data.questions_answered, total_minutes: data.total_minutes,
435	          source: data.source, exported_at: data.exported_at
436	        };
437	        if (usage && (usage.usage_days != null || usage.study_sessions != null ||
438	            usage.questions_answered != null || usage.total_minutes != null)) {
439	          blocks.push('<div class="usage-block"><h3>使用记录汇总</h3><div class="usage-stats">' +
440	            statCard(usage.usage_days, "使用天数", "天") +
441	            statCard(usage.study_sessions, "学习会话数", "次") +
442	            statCard(usage.questions_answered, "做题数", "题") +
443	            statCard(usage.total_minutes, "累计学习时长", "分钟") +
444	            "</div>" + srcLine(usage) + "</div>");
445	        }
446	
447	        var feedback = data.feedback;
448	        if (Array.isArray(feedback) && feedback.length) {
449	          var quotes = feedback.map(function (f) {
450	            return "<li>" + esc(typeof f === "string" ? f : (f.quote || "")) + "</li>";
451	          }).join("");
452	          var meta = Array.isArray(feedback) && feedback[0] && typeof feedback[0] === "object"
453	            ? srcLine(feedback[0]) : "";
