1	:root {
2	  --ink: #1a2333;
3	  --ink-soft: #4a5568;
4	  --ink-faint: #8a94a6;
5	  --bg: #f6f8fb;
6	  --card: #ffffff;
7	  --line: #e3e8f0;
8	  --primary: #2456d6;
9	  --primary-dark: #1a3fa0;
10	  --primary-soft: #eaf0fd;
11	  --ok: #178a50;
12	  --ok-soft: #e6f6ee;
13	  --warn: #b8860b;
14	  --warn-soft: #fdf5e0;
15	  --bad: #c0392b;
16	  --bad-soft: #fdeceb;
17	  --radius: 12px;
