153	#radar-chart { width: 100%; height: 430px; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); }
154	.radar-side { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); padding: 18px 20px; }
155	.radar-side h3 { margin: 0 0 6px; font-size: 16px; }
