157	.legend { display: flex; flex-wrap: wrap; gap: 14px; font-size: 13px; color: var(--ink-soft); margin-bottom: 10px; }
158	.legend .item { display: inline-flex; align-items: center; gap: 6px; }
159	.legend .swatch { width: 12px; height: 12px; border-radius: 3px; display: inline-block; }
160	
161	.blind-list { margin-top: 26px; }
162	table.blind { width: 100%; border-collapse: collapse; background: var(--card); border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; font-size: 14.5px; }
163	table.blind th, table.blind td { padding: 11px 14px; text-align: left; border-bottom: 1px solid var(--line); }
164	table.blind th { background: #f0f4fa; font-size: 13px; white-space: nowrap; }
165	table.blind tr.row-main { cursor: pointer; }
166	table.blind tr.row-main:hover { background: #f7f9fd; }
167	table.blind tr.row-main.open { background: #f0f4fa; }
168	table.blind tr.row-detail > td { padding: 0; border-bottom: 1px solid var(--line); }
169	
170	/* mobile: one card per topic instead of the table */
171	.blind-cards { display: none; }
172	.blind-card {
173	  background: var(--card); border: 1px solid var(--line); border-radius: var(--radius);
174	  margin-bottom: 12px; overflow: hidden;
175	}
176	.blind-card .bc-head { display: flex; align-items: center; gap: 10px; padding: 13px 16px; cursor: pointer; }
177	.blind-card .bc-head:hover { background: #f7f9fd; }
178	.blind-card .bc-name { font-weight: 600; font-size: 15px; flex: 1; }
179	.blind-card .bc-stats {
180	  display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;
181	  padding: 0 16px 13px; font-size: 12.5px; color: var(--ink-faint);
182	}
183	.blind-card .bc-stats b { display: block; font-size: 15px; color: var(--ink); font-weight: 700; }
184	.blind-card .detail-box { border-top: 1px solid var(--line); }
