"""Radar axis-label wrapping checks (09c follow-up), 1440x900 and 375x812."""

import json
import pathlib
import sys

from playwright.sync_api import sync_playwright

BASE = "http://127.0.0.1:18808"
SCRATCH = pathlib.Path(__file__).resolve().parent

REPORT = {}
FAILED = []


def fail(msg):
    FAILED.append(msg)


JS = """
() => {
  const cont = document.getElementById('radar-chart');
  const chart = echarts.getInstanceByDom(cont);
  const names = chart.getOption().radar[0].indicator.map(i => i.name);
  const cr = cont.getBoundingClientRect();
  const allTexts = Array.from(cont.querySelectorAll('svg text, svg tspan'))
    .map(t => ({el: t, text: t.textContent}));
  const rectOf = el => {
    const r = el.getBoundingClientRect();
    if (r.width || r.height) return r;
    // tspan fallback: measure via Range on its text
    const range = document.createRange();
    range.selectNodeContents(el);
    return range.getBoundingClientRect();
  };
  const out = {container: {left: cr.left, right: cr.right, top: cr.top, bottom: cr.bottom},
               labels: [], legend: [], oob: [], bad_breaks: [], legend_overlap: []};
  const legendRects = [];
  allTexts.forEach(({el, text}) => {
    if (!text) return;
    if (text === '覆盖度' || text.indexOf('考试权重') === 0) {
      const r = rectOf(el);
      legendRects.push({text, left: r.left, right: r.right, top: r.top, bottom: r.bottom});
    }
  });
  out.legend = legendRects;
  names.forEach(name => {
    const lines = name.split('\\n');
    const label = {name: name.replace(/\\n/g, ' / '), lines: []};
    lines.forEach(line => {
      const hit = allTexts.find(({text}) => text === line || text.trim() === line.trim());
      if (!hit) { label.lines.push({line, found: false}); return; }
      const r = rectOf(hit.el);
      label.lines.push({line, found: true,
                        left: Math.round(r.left), right: Math.round(r.right),
                        top: Math.round(r.top), bottom: Math.round(r.bottom)});
      if (r.left < cr.left - 1 || r.right > cr.right + 1 ||
          r.top < cr.top - 1 || r.bottom > cr.bottom + 1)
        out.oob.push({line, left: Math.round(r.left - cr.left),
                      right: Math.round(cr.right - r.right),
                      top: Math.round(r.top - cr.top),
                      bottom: Math.round(cr.bottom - r.bottom)});
      // legend overlap (inflate legend rects for the color swatch next to the text)
      legendRects.forEach(lg => {
        const pad = 26;
        if (r.right > lg.left - pad && r.left < lg.right + pad &&
            r.bottom > lg.top - 4 && r.top < lg.bottom + 4)
          out.legend_overlap.push({line, label: lg.text});
      });
    });
    for (let i = 0; i + 1 < lines.length; i++) {
      const a = lines[i].replace(/\\s+$/, '');
      const b = lines[i + 1].replace(/^\\s+/, '');
      if (!a || !b) continue;
      const ca = a.charAt(a.length - 1), cb = b.charAt(0);
      const alnum = c => /[A-Za-z0-9]/.test(c);
      if (alnum(ca) && alnum(cb))
        out.bad_breaks.push({name: label.name, between: ca + '|' + cb});
    }
    out.labels.push(label);
  });
  // every svg text in container must fit (09b check, incl. legend itself)
  out.all_texts_count = allTexts.length;
  out.oob_all = [];
  allTexts.forEach(({el, text}) => {
    if (!text) return;
    const r = rectOf(el);
    if (!r.width && !r.height) return;
    if (r.left < cr.left - 1 || r.right > cr.right + 1 ||
        r.top < cr.top - 1 || r.bottom > cr.bottom + 1)
      out.oob_all.push(text.slice(0, 30));
  });
  return out;
}
"""


def main() -> int:
    with sync_playwright() as p:
        browser = p.chromium.launch(channel="chrome", headless=True)
        for label, w, h, shot in [
                ("desktop_1440", 1440, 900, "site-09c2-desktop.png"),
                ("mobile_375", 375, 812, "site-09c2-mobile.png")]:
            page = browser.new_page(viewport={"width": w, "height": h})
            errors = []
            page.on("pageerror", lambda e: errors.append(str(e)))
            page.goto(BASE + "/", wait_until="networkidle")
            page.wait_for_timeout(1500)
            out = page.evaluate(JS)
            REPORT[label] = out
            if out["oob"]:
                fail(f"{label}: label lines out of container: {out['oob']}")
            if out["oob_all"]:
                fail(f"{label}: svg texts out of container: {out['oob_all']}")
            if out["legend_overlap"]:
                fail(f"{label}: label lines overlap legend: {out['legend_overlap']}")
            if out["bad_breaks"]:
                fail(f"{label}: break inside ASCII word: {out['bad_breaks']}")
            missing = [l["line"] for lab in out["labels"] for l in lab["lines"] if not l["found"]]
            if missing:
                fail(f"{label}: DOM line not found for: {missing}")
            if errors:
                fail(f"{label}: page errors: {errors}")
            page.screenshot(path=str(SCRATCH / shot), full_page=True)
            page.close()
        browser.close()

    print(json.dumps(REPORT, ensure_ascii=False, indent=2))
    print("\n".join("FAILED: " + f for f in FAILED) if FAILED else "ALL RADAR LABEL CHECKS PASSED")
    return 1 if FAILED else 0


if __name__ == "__main__":
    sys.exit(main())

